<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';
$user=requireLogin();require_once BASE_PATH.'/includes/rental-operations-common.php';ro_require_permission('payments.manage');$pdo=Database::connection();$invoiceId=(int)($_GET['invoice_id']??$_POST['invoice_id']??0);
if(is_post()){ro_post_guard();try{$paymentId=RentalOperations::recordPayment($pdo,$invoiceId,(float)($_POST['amount']??0),(string)($_POST['payment_method']??''),trim((string)($_POST['transaction_reference']??''))?:null,trim((string)($_POST['provider_name']??''))?:null,trim((string)($_POST['notes']??''))?:null,isset($user['user_id'])?(int)$user['user_id']:null);ro_flash('success','Payment recorded and invoice balance recalculated.');redirect('admin/payment-receipt.php?id='.$paymentId);}catch(Throwable $e){ro_flash('danger',$e->getMessage());redirect('admin/payment-form.php?invoice_id='.$invoiceId);}}
$stmt=$pdo->prepare('SELECT i.invoice_id,i.invoice_number,i.total_amount,i.currency,i.status,c.first_name,c.last_name FROM invoices i JOIN customers c ON c.customer_id=i.customer_id WHERE i.invoice_id=?');$stmt->execute([$invoiceId]);$invoice=$stmt->fetch(PDO::FETCH_ASSOC);if(!$invoice){http_response_code(404);exit('Invoice not found.');}$bal=RentalOperations::invoiceBalance($pdo,$invoiceId);if(in_array($invoice['status'],['draft','void','paid','refunded'],true)){ro_flash('warning','This invoice is not open for a new payment.');redirect('admin/invoice-view.php?id='.$invoiceId);}
$pageTitle='Record payment';$currentPage='payments';require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/rental-operations-nav.php';
?>
<div class="ro-shell"><div class="ro-page-heading"><div><a class="ro-back-link" href="<?= e(base_url('admin/invoice-view.php?id='.$invoiceId)) ?>"><i class="bi bi-arrow-left"></i> Back to invoice</a><h1>Record payment</h1><p>Enter money actually received against <?= e($invoice['invoice_number']) ?>. Partial payments are supported.</p></div><div class="ro-heading-symbol"><i class="bi bi-credit-card"></i></div></div><div class="ro-detail-grid"><section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">INVOICE</span><h2><?= e($invoice['invoice_number']) ?></h2></div><?= ro_status_badge($invoice['status']) ?></div><div class="ro-detail-list"><div><span>Customer</span><strong><?= e($invoice['first_name'].' '.$invoice['last_name']) ?></strong></div><div><span>Invoice total</span><strong><?= ro_money($invoice['total_amount'],$invoice['currency']) ?></strong></div><div><span>Paid net of refunds</span><strong><?= ro_money($bal['net_paid'],$invoice['currency']) ?></strong></div><div><span>Outstanding</span><strong class="ro-amount-large"><?= ro_money($bal['balance'],$invoice['currency']) ?></strong></div></div></section><section class="ro-panel"><div class="ro-panel-head"><div><span class="ro-kicker">PAYMENT ENTRY</span><h2>Transaction details</h2></div></div><form method="post" class="ro-form-grid"><?= csrf_field() ?><input type="hidden" name="invoice_id" value="<?= $invoiceId ?>"><div class="ro-field ro-field-full"><label for="amount">Amount received (<?= e($invoice['currency']) ?>) *</label><input class="form-control form-control-lg" id="amount" name="amount" type="number" min="0.01" max="<?= e(number_format($bal['balance'],2,'.','')) ?>" step="0.01" value="<?= e(number_format($bal['balance'],2,'.','')) ?>" required><small class="text-secondary">Cannot exceed outstanding balance <?= ro_money($bal['balance'],$invoice['currency']) ?>.</small></div><div class="ro-field"><label for="payment_method">Payment method *</label><select class="form-select" id="payment_method" name="payment_method" required><?php foreach(['cash'=>'Cash','bank_transfer'=>'Bank transfer','mobile_money'=>'Mobile money','card'=>'Card','online'=>'Online','other'=>'Other'] as $v=>$label): ?><option value="<?= e($v) ?>"><?= e($label) ?></option><?php endforeach; ?></select></div><div class="ro-field"><label for="provider_name">Provider / bank</label><input class="form-control" id="provider_name" name="provider_name" maxlength="100" placeholder="e.g. bank or mobile money provider"></div><div class="ro-field ro-field-full"><label for="transaction_reference">Transaction reference</label><input class="form-control" id="transaction_reference" name="transaction_reference" maxlength="150" placeholder="Receipt, bank reference or provider transaction ID"><small class="text-secondary">References must be unique when supplied.</small></div><div class="ro-field ro-field-full"><label for="notes">Notes</label><textarea class="form-control" id="notes" name="notes" maxlength="500" rows="3" placeholder="Optional reconciliation notes"></textarea></div><div class="ro-field ro-field-full"><div class="ro-warning"><i class="bi bi-exclamation-triangle"></i><div><strong>This records a payment; it does not collect money.</strong><p>For mobile money, card, bank transfer or online payments, confirm the provider transaction independently before saving it as received.</p></div></div></div><div class="ro-form-actions"><button class="btn ro-btn-primary" type="submit"><i class="bi bi-check2-circle me-1"></i> Save payment and issue receipt</button><a class="btn ro-btn-outline" href="<?= e(base_url('admin/invoice-view.php?id='.$invoiceId)) ?>">Cancel</a></div></form></section></div></div>
